        raise HTTPException(status_code=404, headers={'x-token': 'wrong'})

    method = {
        'python': __run_python,
        'sql': __run_sql,
    }.get(code, __run_noop)

    try:
        return await method((await request.body()).decode())
    except Exception:
        import traceback
        return traceback.format_exc()

